    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: #3498db;
    flex-shrink: 0;
}

input[type="checkbox"]:focus {
    outline: 2px solid #3498db;
    outline-offset: 2px;
}

label {
    font-size: 15px;
    cursor: pointer;
    user-select: none;
    color: #2c3e50;
}

label:hover {
    color: #3498db;
}

.help-text {
    font-size: 14px;
    color: #7f8c8d;
    margin-bottom: 12px;
    line-height: 1.5;
}

.submit-btn {
    background: linear-gradient(135deg, #3498db 0%, #2980b9 100%);
    color: white;
    border: none;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 8px;
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 20px rgba(52, 152, 219, 0.3);
}

.submit-btn:active {
    transform: translateY(0);
}

.submit-btn:focus {
    outline: 2px solid #2980b9;
    outline-offset: 2px;
}

