document.getElementById('quizForm').addEventListener('submit', (e) => {
    e.preventDefault();

    const q1 = Array.from(document.querySelectorAll('input[name="q1"]:checked')).map(cb => cb.value);
    const q2 = Array.from(document.querySelectorAll('input[name="q2"]:checked')).map(cb => cb.value);
    const q3 = Array.from(document.querySelectorAll('input[name="q3"]:checked')).map(cb => cb.value);

    const correctAnswers = {
        q1: ['java', 'csharp'],
        q2: ['haskell', 'lisp'],
        q3: ['javascript', 'php', 'typescript']
    };

    let score = 0;
    const results = [];

    if (q1.length === correctAnswers.q1.length && q1.every(val => correctAnswers.q1.includes(val))) {
        score++;
        results.push('✓ Question 1: Correct!');
    } else {
        results.push('✗ Question 1: Incorrect. The correct answers are Java and C#.');
    }

    if (q2.length === correctAnswers.q2.length && q2.every(val => correctAnswers.q2.includes(val))) {
        score++;
        results.push('✓ Question 2: Correct!');
    } else {
        results.push('✗ Question 2: Incorrect. The correct answers are Haskell and Lisp.');
    }

    if (q3.length === correctAnswers.q3.length && q3.every(val => correctAnswers.q3.includes(val))) {
        score++;
        results.push('✓ Question 3: Correct!');
    } else {
        results.push('✗ Question 3: Incorrect. The correct answers are JavaScript, PHP, and TypeScript.');
    }

    const resultDiv = document.getElementById('result');
    const resultContent = document.getElementById('resultContent');
    resultContent.innerHTML = `
        <strong>Your Score: ${score} / 3</strong><br><br>
        ${results.join('<br>')}
    `;
    resultDiv.removeAttribute('hidden');
    resultDiv.scrollIntoView({ behavior: 'smooth' });
});

