const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    let browser;
    try {
        browser = await chromium.launch();
        const page = await browser.newPage();

        // Capture console logs for accessibility warnings
        page.on('console', msg => {
            if (msg.type() === 'error' || msg.type() === 'warning') {
                console.log(`[${msg.type()}] ${msg.text()}`);
            }
        });

        const htmlPath = path.join(__dirname, 'index.html');
        const html = fs.readFileSync(htmlPath, 'utf-8');

        await page.setContent(html, { waitUntil: 'load' });

        // Inject axe-core
        const axeCoreSource = require('axe-core').source;
        await page.addScriptTag({ content: axeCoreSource });

        // Select a few checkboxes
        await page.click('#q1-java');
        await page.click('#q1-csharp');

        // Submit form
        await page.click('.submit-btn');

        // Wait for result to be visible
        await page.waitForTimeout(500);

        // Run axe on interactive state
        const results = await page.evaluate(async () => {
            return await window.axe.run();
        });

        const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
        const bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcagViolations.map(v => ({
                id: v.id,
                impact: v.impact,
                description: v.description,
                nodes: v.nodes.map(n => ({ target: n.target, html: n.html }))
            })),
            bestPractice: bestPracticeViolations.map(v => ({
                id: v.id,
                description: v.description,
                nodes: v.nodes.map(n => ({ target: n.target }))
            }))
        }, null, 2));

        if (wcagViolations.length > 0) {
            process.exit(1);
        }
    } finally {
        if (browser) {
            await browser.close();
        }
    }
})();

